 p=dict(refdata_id='emptydrops_unfiltered_input',source_url='https://bioconductor.org/packages/DropletUtils/',version='synthetic-v1',licence='Synthetic software fixture; no clinical data',permitted_use='Software validation only',sha256=hashlib.sha256(f.read_bytes()).hexdigest(),species='human',unfiltered_raw_counts=True);(out/(f.name+'.json')).write_text(json.dumps(p))
